<template>
  <section class="flex flex-col gap-4">
    <Alert v-if="projectTabStatus" variant="warning" class="bg-card w-fit">
      <div class="flex items-center gap-2">
        <TriangleAlert class="size-5 stroke-warning-foreground w-5" />
        <AlertTitle class="w-fit mb-0">{{ projectTabStatus.title }} {{ projectTabStatus.subtitle }}</AlertTitle>
      </div>
    </Alert>
    <GoBackButton
      subject="project"
      :fallback-to="{ name: 'projects-id', params: { id: useRoute('projects-id-edit').params?.id?.toString() } }"
    />
    <NuxtPage />
  </section>
</template>

<script lang="ts" setup>
import { projectEditAlerts } from '~/constants/projects/projectEditAlerts';
import { TriangleAlert } from 'lucide-vue-next';
import type { ProjectEditTabsStatusResponse } from '~/client';

definePageMeta({
  roles: ['admin'],
});

interface Props {
  tabStatus?: ProjectEditTabsStatusResponse;
}

const props = defineProps<Props>();

const projectTabStatus = computed(() => {
  const tab: string = useRoute().path.split('/edit/')[1]?.replaceAll('-', '_');
  let item;
  if (props.tabStatus && tab) {
    Object.entries(props.tabStatus).forEach(([key, value]) => {
      if (key === tab) {
        item = value;
      }
    });
  }
  return item ? projectEditAlerts[tab][item] : null;
});
</script>

<style lang="scss" scoped></style>
